/**
 * The Keys type is used by core APIs to dynamically resolve IDs
 * defined in a Fluent project. In the core package itself, this
 * type contains no IDs and thus cannot be used. Fluent projects
 * must override this type in their keys.ts file like so:
 *
 *     declare global {
 *         namespace Now {
 *             namespace Internal {
 *                 interface Keys extends KeysRegistry {
 *                     ...
 *                 }
 *             }
 *         }
 *     }
 *
 * Once a keys.ts file is defined with this structure, IDs can be
 * used in Fluent code using Now.ID('something') and, if the key
 * provided as an argument exists locally as an explicit key, it
 * will provide the concrete value containing the table name and
 * sys ID for that key. If the key provided doesn't exist yet, it
 * will be returned as `any` and the build system will generate a
 * new entry for it in the keys.ts file.
 */
interface Keys extends Now.Internal.KeysRegistry {}

declare global {
    namespace Now {
        namespace Internal {
            type ExplicitKeys = Keys['explicit']
            type ExplicitKey<Table extends string = string> = {
                table: Table
                id: string
                deleted?: boolean | undefined
            }

            type NestedKeys = { [key: string]: string | { id: string; key: NestedKeys } }
            type CompositeKey<Table extends string = string> = ExplicitKey<Table> & {
                key: NestedKeys
            }

            type AnyKey<Table extends string = string> = ExplicitKey<Table> & {
                key?: NestedKeys
            }

            interface KeysRegistry {
                explicit: Record<string | number, ExplicitKey>
                composite: CompositeKey[]
                deleted: Record<string, string[]>
            }

            type WithID<T> = {
                $id: ExplicitKey | string | number
            } & T

            /** Brands an API return type with its target table name, enabling it to be used as a reference value in Record() data fields. */
            type TableBrand<Table extends string> = { readonly __table__: Table }

            type Meta = {
                $meta?: {
                    /** Map a record to an output folder that loads only in specific circumstances.
                     * 'first install' - > 'unload',
                     * 'demo' -> 'unload.demo' */
                    installMethod?: 'first install' | 'demo'
                }
            }
        }

        const ID: Internal.ExplicitKeys & Record<string | number, any>
    }
}
